<?php use Sigesp\Core\View; $page = (int) ($page ?? 1); $pages = max(1, (int) ($pages ?? 1)); $baseUrl = $baseUrl ?? '#'; ?>
<nav class="pagination" aria-label="Paginação"><a href="<?= View::e($baseUrl) ?>&page=<?= max(1, $page - 1) ?>" aria-label="Página anterior">Anterior</a><?php for ($number = max(1, $page - 2); $number <= min($pages, $page + 2); $number++): ?><a href="<?= View::e($baseUrl) ?>&page=<?= $number ?>" class="<?= $number === $page ? 'is-current' : '' ?>" aria-current="<?= $number === $page ? 'page' : 'false' ?>"><?= $number ?></a><?php endfor; ?><a href="<?= View::e($baseUrl) ?>&page=<?= min($pages, $page + 1) ?>" aria-label="Próxima página">Próxima</a></nav>
